using ContosoUniversity.Data;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Helpers;

public static class TestDbContextFactory
{
    public static SchoolContext Create(string? dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;

        var context = new SchoolContext(options);
        context.Database.EnsureCreated();
        return context;
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut = new();

    public void Dispose() => _sut.Dispose();

    [Fact]
    public void SendNotification_WithDisplayName_GeneratesCorrectMessage()
    {
        // Act
        _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("John Doe", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityId()
    {
        // Act
        _sut.SendNotification("Course", "42", EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("ID: 42", notification.Message);
        Assert.Contains("updated", notification.Message);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectVerb(EntityOperation operation, string expectedVerb)
    {
        // Act
        _sut.SendNotification("Department", "5", "Engineering", operation, "User1");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains(expectedVerb, notification.Message);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        // Drain any leftover notifications from other tests (static queue)
        while (_sut.ReceiveNotification() != null) { }

        // Act
        var result = _sut.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public void SendNotification_MultipleMessages_DequeuedInOrder()
    {
        // Drain queue first
        while (_sut.ReceiveNotification() != null) { }

        // Arrange & Act
        _sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);
        _sut.SendNotification("C", "3", "Third", EntityOperation.DELETE);

        // Assert - FIFO order
        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();
        var third = _sut.ReceiveNotification();

        Assert.Equal("A", first!.EntityType);
        Assert.Equal("B", second!.EntityType);
        Assert.Equal("C", third!.EntityType);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        // Act
        var before = DateTime.Now;
        _sut.SendNotification("Test", "1", "Entity", EntityOperation.CREATE);
        var after = DateTime.Now;

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op for in-memory implementation but should not throw
        var exception = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(exception);
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        SeedStudents();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private void SeedStudents()
    {
        _context.Students.AddRange(
            new Student { FirstMidName = "Alice", LastName = "Anderson", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { FirstMidName = "Bob", LastName = "Brown", EnrollmentDate = new DateTime(2021, 9, 1) },
            new Student { FirstMidName = "Charlie", LastName = "Clark", EnrollmentDate = new DateTime(2019, 9, 1) }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_NoParameters_ReturnsViewWithStudentsOrderedByLastName()
    {
        // Act
        var result = _controller.Index(null, null, null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
        Assert.Equal("Anderson", model[0].LastName);
        Assert.Equal("Brown", model[1].LastName);
        Assert.Equal("Clark", model[2].LastName);
    }

    [Fact]
    public void Index_NameDescSort_ReturnsDescendingOrder()
    {
        // Act
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Clark", model[0].LastName);
        Assert.Equal("Brown", model[1].LastName);
        Assert.Equal("Anderson", model[2].LastName);
    }

    [Theory]
    [InlineData("Date", "Clark", "Anderson", "Brown")]   // ascending by enrollment date
    [InlineData("date_desc", "Brown", "Anderson", "Clark")] // descending by enrollment date
    public void Index_DateSort_ReturnsCorrectOrder(string sortOrder, string first, string second, string third)
    {
        // Act
        var result = _controller.Index(sortOrder, null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(first, model[0].LastName);
        Assert.Equal(second, model[1].LastName);
        Assert.Equal(third, model[2].LastName);
    }

    [Theory]
    [InlineData("Alice", 1)]
    [InlineData("Brown", 1)]
    [InlineData("nonexistent", 0)]
    public void Index_SearchString_FiltersResults(string searchString, int expectedCount)
    {
        // Act
        var result = _controller.Index(null, null, searchString, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(expectedCount, model.Count);
    }

    [Fact]
    public void Index_SearchStringProvided_ResetsPageTo1()
    {
        // Act
        _controller.Index(null, null, "Alice", 5);

        // Assert - ViewBag.CurrentFilter should be set
        Assert.Equal("Alice", _controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Index_NullSearchString_UsesCurrentFilter()
    {
        // Act
        _controller.Index(null, "Bob", null, null);

        // Assert
        Assert.Equal("Bob", _controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        // Arrange
        var student = _context.Students.First();

        // Act
        var result = _controller.Details(student.ID) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithDefaultDate()
    {
        // Act
        var result = _controller.Create() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        // Arrange
        var student = new Student
        {
            FirstMidName = "Diana",
            LastName = "Davis",
            EnrollmentDate = new DateTime(2023, 1, 15)
        };

        // Act
        var result = _controller.Create(student);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(4, _context.Students.Count());
    }

    [Fact]
    public void Create_Post_DefaultEnrollmentDate_AddsModelError()
    {
        // Arrange
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = DateTime.MinValue
        };

        // Act
        var result = _controller.Create(student);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_Post_EnrollmentDateBefore1753_AddsModelError()
    {
        // Arrange
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        // Act
        var result = _controller.Create(student);

        // Assert
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        // Arrange
        var student = _context.Students.First();

        // Act
        var result = _controller.Edit(student.ID) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Edit(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Edit(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Post_ValidStudent_RedirectsToIndex()
    {
        // Arrange
        var student = _context.Students.First();
        student.LastName = "UpdatedName";

        // Detach to simulate form post
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        // Act
        var result = _controller.Edit(student);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_DefaultEnrollmentDate_AddsModelError()
    {
        // Arrange
        var student = _context.Students.First();
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
        student.EnrollmentDate = default;

        // Act
        var result = _controller.Edit(student);

        // Assert
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        // Arrange
        var student = _context.Students.First();

        // Act
        var result = _controller.Delete(student.ID) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Delete(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Delete(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        // Arrange
        var student = _context.Students.First();
        var initialCount = _context.Students.Count();

        // Act
        var result = _controller.DeleteConfirmed(student.ID);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(initialCount - 1, _context.Students.Count());
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _envMock;
    private readonly Mock<ILogger<CoursesController>> _loggerMock;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.Create();
        SeedData();
        _envMock = new Mock<IWebHostEnvironment>();
        _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _envMock.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _loggerMock = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private void SeedData()
    {
        var dept = new Department { Name = "Science", Budget = 100000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        _context.Courses.AddRange(
            new Course { CourseID = 101, Title = "Physics", Credits = 3, DepartmentID = dept.DepartmentID },
            new Course { CourseID = 102, Title = "Biology", Credits = 4, DepartmentID = dept.DepartmentID }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_ReturnsViewWithAllCourses()
    {
        // Act
        var result = _controller.Index() as ViewResult;

