using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        SeedStudents();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private void SeedStudents()
    {
        _context.Students.AddRange(
            new Student { FirstMidName = "Alice", LastName = "Anderson", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { FirstMidName = "Bob", LastName = "Brown", EnrollmentDate = new DateTime(2021, 9, 1) },
            new Student { FirstMidName = "Charlie", LastName = "Clark", EnrollmentDate = new DateTime(2019, 9, 1) }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_NoParameters_ReturnsViewWithStudentsOrderedByLastName()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
        Assert.Equal("Anderson", model[0].LastName);
        Assert.Equal("Brown", model[1].LastName);
        Assert.Equal("Clark", model[2].LastName);
    }

    [Fact]
    public void Index_NameDescSort_ReturnsDescendingOrder()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Clark", model[0].LastName);
        Assert.Equal("Brown", model[1].LastName);
        Assert.Equal("Anderson", model[2].LastName);
    }

    [Theory]
    [InlineData("Date", "Clark", "Anderson", "Brown")]
    [InlineData("date_desc", "Brown", "Anderson", "Clark")]
    public void Index_DateSort_ReturnsCorrectOrder(string sortOrder, string first, string second, string third)
    {
        var result = _controller.Index(sortOrder, null, null, null) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(first, model[0].LastName);
        Assert.Equal(second, model[1].LastName);
        Assert.Equal(third, model[2].LastName);
    }

    [Theory]
    [InlineData("Alice", 1)]
    [InlineData("Brown", 1)]
    [InlineData("nonexistent", 0)]
    public void Index_SearchString_FiltersResults(string searchString, int expectedCount)
    {
        var result = _controller.Index(null, null, searchString, null) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(expectedCount, model.Count);
    }

    [Fact]
    public void Index_SearchStringProvided_ResetsPageTo1()
    {
        _controller.Index(null, null, "Alice", 5);
        Assert.Equal("Alice", _controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Index_NullSearchString_UsesCurrentFilter()
    {
        _controller.Index(null, "Bob", null, null);
        Assert.Equal("Bob", _controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        var student = _context.Students.First();
        var result = _controller.Details(student.ID) as ViewResult;
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithDefaultDate()
    {
        var result = _controller.Create() as ViewResult;
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            FirstMidName = "Diana",
            LastName = "Davis",
            EnrollmentDate = new DateTime(2023, 1, 15)
        };

        var result = _controller.Create(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(4, _context.Students.Count());
    }

    [Fact]
    public void Create_Post_DefaultEnrollmentDate_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = DateTime.MinValue
        };

        _controller.Create(student);

        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_Post_EnrollmentDateBefore1753_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        _controller.Create(student);

        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        var student = _context.Students.First();
        var result = _controller.Edit((int?)student.ID) as ViewResult;
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit((int?)9999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Post_ValidStudent_RedirectsToIndex()
    {
        var student = _context.Students.First();
        student.LastName = "UpdatedName";
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var result = _controller.Edit(student: student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_DefaultEnrollmentDate_AddsModelError()
    {
        var student = _context.Students.First();
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
        student.EnrollmentDate = default;

        _controller.Edit(student: student);

        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        var student = _context.Students.First();
        var result = _controller.Delete(student.ID) as ViewResult;
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(9999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        var student = _context.Students.First();
        var initialCount = _context.Students.Count();

        var result = _controller.DeleteConfirmed(student.ID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(initialCount - 1, _context.Students.Count());
    }
}

