using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests : IDisposable
{
    private readonly SchoolContext _context;

    public SchoolContextTests()
    {
        _context = TestDbContextFactory.Create();
    }

    public void Dispose() => _context.Dispose();

    [Fact]
    public void CanAddAndRetrieveStudent()
    {
        var student = new Student { FirstMidName = "Test", LastName = "Student", EnrollmentDate = new DateTime(2020, 1, 1) };
        _context.Students.Add(student);
        _context.SaveChanges();

        var retrieved = _context.Students.Find(student.ID);
        Assert.NotNull(retrieved);
        Assert.Equal("Student", retrieved.LastName);
        Assert.Equal("Test", retrieved.FirstMidName);
    }

    [Fact]
    public void CanAddAndRetrieveCourse()
    {
        var dept = new Department { Name = "TestDept", Budget = 50000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 5000, Title = "Test Course", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Include(c => c.Department).First(c => c.CourseID == 5000);
        Assert.Equal("Test Course", retrieved.Title);
        Assert.Equal("TestDept", retrieved.Department.Name);
    }

    [Fact]
    public void CourseAssignment_HasCompositeKey()
    {
        var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() };
        _context.Instructors.Add(instructor);
        var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 9001, Title = "C", Credits = 1, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var assignment = new CourseAssignment { CourseID = 9001, InstructorID = instructor.ID };
        _context.CourseAssignments.Add(assignment);
        _context.SaveChanges();

        var found = _context.CourseAssignments.Find(9001, instructor.ID);
        Assert.NotNull(found);
    }

    [Fact]
    public void Instructor_OfficeAssignment_OneToOne()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Test",
            LastName = "Prof",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>(),
            OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors
            .Include(i => i.OfficeAssignment)
            .First(i => i.ID == instructor.ID);
        Assert.NotNull(retrieved.OfficeAssignment);
        Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
    }

    [Fact]
    public void Enrollment_RelatesStudentAndCourse()
    {
        var student = new Student { FirstMidName = "E", LastName = "Student", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        var dept = new Department { Name = "Dept", Budget = 1000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 7777, Title = "Course", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var enrollment = new Enrollment { StudentID = student.ID, CourseID = 7777, Grade = Grade.A };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var retrieved = _context.Enrollments
            .Include(e => e.Student)
            .Include(e => e.Course)
            .First(e => e.EnrollmentID == enrollment.EnrollmentID);
        Assert.Equal(Grade.A, retrieved.Grade);
        Assert.Equal("Student", retrieved.Student.LastName);
        Assert.Equal("Course", retrieved.Course.Title);
    }

    [Fact]
    public void Department_RowVersion_IsTimestamp()
    {
        var dept = new Department { Name = "VersionTest", Budget = 5000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        // In InMemory provider, RowVersion may not be auto-generated but the mapping exists
        var entity = _context.Model.FindEntityType(typeof(Department));
        var rowVersion = entity!.FindProperty("RowVersion");
        Assert.NotNull(rowVersion);
        Assert.True(rowVersion.IsConcurrencyToken);
    }
}

using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Data;

public class DbInitializerTests : IDisposable
{
    private readonly SchoolContext _context;

    public DbInitializerTests()
    {
        _context = TestDbContextFactory.Create();
    }

    public void Dispose() => _context.Dispose();

    [Fact]
    public void Initialize_EmptyDatabase_SeedsAllData()
    {
        // Act
        DbInitializer.Initialize(_context);

        // Assert
        Assert.Equal(8, _context.Students.Count());
        Assert.Equal(5, _context.Instructors.Count());
        Assert.Equal(4, _context.Departments.Count());
        Assert.Equal(7, _context.Courses.Count());
        Assert.Equal(3, _context.OfficeAssignments.Count());
        Assert.True(_context.CourseAssignments.Count() > 0);
        Assert.True(_context.Enrollments.Count() > 0);
    }

    [Fact]
    public void Initialize_AlreadySeeded_DoesNotDuplicate()
    {
        // Arrange - seed once
        DbInitializer.Initialize(_context);
        var studentCount = _context.Students.Count();

        // Act - seed again
        DbInitializer.Initialize(_context);

        // Assert - counts unchanged
        Assert.Equal(studentCount, _context.Students.Count());
    }

    [Fact]
    public void Initialize_CreatesExpectedStudents()
    {
        DbInitializer.Initialize(_context);

        Assert.Contains(_context.Students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
        Assert.Contains(_context.Students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
    }

    [Fact]
    public void Initialize_CreatesDepartmentsWithAdministrators()
    {
        DbInitializer.Initialize(_context);

        var engineering = _context.Departments.First(d => d.Name == "Engineering");
        Assert.NotNull(engineering.InstructorID);
    }

    [Fact]
    public void Initialize_CreatesEnrollmentsWithGrades()
    {
        DbInitializer.Initialize(_context);

        var enrollments = _context.Enrollments.ToList();
        Assert.Contains(enrollments, e => e.Grade == Grade.A);
        Assert.Contains(enrollments, e => e.Grade == Grade.B);
        Assert.Contains(enrollments, e => e.Grade == null); // Anand has no grade in Chemistry
    }
}

